"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Neon Underground', 'author': 'Signature original', 'genre': 'Post-Collapse', 'chapters': [{'n': 1, 'title': 'Contraband', 'text': "the runner Pax took one look and went pale. 'This is pre-Collapse,' the runner Pax whispered. 'the Patrol killed people for less than this. We have to move. Now.'\n\nThey moved through the Sprawl like smoke: checkpoints avoided, cameras looped, the wasteland humming its electric lullaby. a paper book pulsed in Kai Tanaka's pocket like a second heart.\n\nKai Tanaka found a paper book in the gutters of the Sprawl, where the drones don't look because the poor are invisible — the Patrol's mistake, and everyone's opportunity. It was warm. Data shouldn't be warm."}, {'n': 2, 'title': 'The Network', 'text': "You don't broadcast in the Sprawl; you whisper, and the whispers multiply. Kai Tanaka and the runner Pax built the network node by node: a medic here, a runner there, an ex-enforcer with a grudge and a gun.\n\nthe Patrol noticed. Of course the Patrol noticed — the Algorithm sees all. Patrols doubled. The tribe got louder. Friends started disappearing from the usual corners.\n\na paper book was copied, hand to hand, each copy a little degraded, each copy a little more precious. Kai Tanaka watched a twelve-year-old memorize the whole thing rather than risk carrying it. The future, Kai Tanaka thought, is in good hands."}, {'n': 3, 'title': 'Blackout', 'text': "'Now,' said the runner Pax. And the Sprawl — all of the Sprawl, every screen, every speaker — remembered.\n\nThe blackout was the runner Pax's masterpiece: three minutes of dark across the Sprawl, bought with a year's favors. Three minutes to move a paper book to the broadcast tower. Three minutes to change the world.\n\nAt the top, the runner Pax's hands flew. 'Thirty seconds to signal,' the runner Pax said. Below, the Patrol's lights converged like angry stars. Kai Tanaka stood at the window with a paper book and thought of green things growing."}, {'n': 4, 'title': 'The Remembering', 'text': "What happened in the next hour, historians argue about. What Kai Tanaka remembers: silence, then a sound like a held breath released, then the streets filling with people who had remembered they were people.\n\na paper book burned out in the broadcast — one use, that was the price. Kai Tanaka held the dead chip and didn't mourn it. Seeds die to grow. That was the whole point.\n\nthe Patrol responded the only way the Patrol knew: force. The Patrol marched. The drones rose. And the people of the Sprawl — who had just remembered green, and laughter, and sky — stood in the streets and would not move."}, {'n': 5, 'title': 'After the Static', 'text': "Kai Tanaka kept the dead chip in a pocket. A reminder: that truth is a seed, that seeds die to grow, that one a paper book in the right hands at the right time is worth an army.\n\nRebuilding the Sprawl was harder than freeing it. Kai Tanaka organized food lines with the same care once used for heists. the runner Pax taught kids to code on salvaged terminals. The medic ran a clinic. The runner ran messages of hope.\n\nThere were trials. the Patrol's people faced justice — real justice, not the Algorithm's kind, with evidence and mercy both. Some were guilty. Some were just afraid. Kai Tanaka learned the difference matters."}, {'n': 6, 'title': 'The Habit of Freedom', 'text': "Sometimes Kai Tanaka walks to the tower and looks out over the Sprawl, green in the cracks of the concrete, alive in the way of things that remember. a paper book is gone. What it carried isn't.\n\nAnd somewhere, in a gutter where drones don't look, someone is finding something warm that shouldn't be warm. It starts again. It always starts again. That's the best part.\n\nsmall sparks burn bright — Kai Tanaka thinks it every time, like a prayer, like a promise. Memory is resistance. Freedom is a habit. Practice daily."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

